<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Available premises</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f5f6f8}.wrap{max-width:1050px;margin:auto;padding:30px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px}.card{background:#fff;border-radius:14px;padding:20px;box-shadow:0 1px 5px #0002}a{color:inherit}.muted{color:#667085}.tag{display:inline-block;background:#eef2f6;padding:4px 8px;border-radius:99px;margin:2px;font-size:12px}</style></head><body><main class="wrap"><h1>Available spaces</h1><p class="muted">Only approved and currently published listings appear here.</p><div class="grid">@forelse($vacancies as $vacancy)<article class="card"><h2><a href="{{ route('managedpremises.public.vacancies.show',$vacancy['slug']) }}">{{ $vacancy['title'] }}</a></h2><div class="muted">{{ $vacancy['location'] ?: 'Location available on enquiry' }}</div><p>{{ $vacancy['summary'] }}</p>@foreach($vacancy['features'] as $feature)<span class="tag">{{ $feature }}</span>@endforeach<div class="muted" style="margin-top:15px">Available {{ $vacancy['available_from'] ?: 'now' }}</div></article>@empty<div class="card">No spaces are currently advertised.</div>@endforelse</div></main></body></html>
